  cheatsheet: [
    { term: "Rigidité", def: "Une modification entraîne un effet domino sur de nombreux modules." },
    { term: "Fragilité", def: "Le logiciel casse à des endroits sans rapport avec la modification." },
    { term: "Immobilité", def: "Impossible de réutiliser un composant ailleurs (soudé au contexte)." },
    { term: "Viscosité", def: "Le hack est plus facile que le bon design. Remède : rendre le bon chemin moins coûteux." },
    { term: "Complexité inutile", def: "Sur-ingénierie, abstractions prématurées. Principe YAGNI." },
    { term: "Répétition inutile", def: "Copier/coller par manque d'abstraction. Principe DRY." },
    { term: "Opacité", def: "Code difficile à lire et comprendre." },
    { term: "SRP", def: "Une classe = une seule raison de changer." },
    { term: "OCP", def: "Ouvert à l'extension, fermé à la modification (interface + polymorphisme au lieu de switch)." },
    { term: "LSP", def: "Une sous-classe remplace sa mère sans casser le comportement (Pingouin/voler)." },
    { term: "ISP", def: "Aucun client ne dépend de méthodes qu'il n'utilise pas : petites interfaces." },
    { term: "DIP", def: "Haut et bas niveau dépendent d'abstractions. Base de l'architecture hexagonale." },
    { term: "REP", def: "Granularité de réutilisation = granularité de release. Versionner (SemVer)." },
    { term: "CCP", def: "Classes qui changent ensemble regroupées ensemble. = SRP des packages. Grands packages." },
    { term: "CRP", def: "Réutiliser une classe = réutiliser tout le package. = ISP des packages. Petits packages." },
    { term: "ADP", def: "Graphe de packages sans cycle (DAG). Casser via DIP ou nouveau package." },
    { term: "SDP", def: "Dépendre vers plus stable (I plus faible). Volatil → stable." },
    { term: "SAP", def: "Plus stable ⇒ plus abstrait. A + I = 1." },
    { term: "Ca / Ce", def: "Ca = classes extérieures qui dépendent de moi (responsabilité) ; Ce = classes extérieures dont je dépends (dépendance)." },
    { term: "I", def: "I = Ce / (Ca + Ce). 0 = stable, 1 = instable." },
    { term: "A", def: "A = Na / Nc (abstraites + interfaces / total)." },
    { term: "D", def: "D = |A + I − 1|, idéal proche de 0. Utilisable en CI/CD." },
    { term: "Zone de rigidité", def: "I = 0, A = 0 : stable et concret (ex. schéma BDD brut)." },
    { term: "Zone d'inutilité", def: "I = 1, A = 1 : instable et abstrait, aucun client." },
  ],
